<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Accessor\MessageSendAtAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the MessageSendAtAccessor trait.
 *
 * Covers null default, string/VO assignment via withSendAt,
 * getSendAt/sendAt accessors, and isSendAtChanged with/without original.
 */
class MessageSendAtAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSendAt creates a new instance with the SendAt set
     * from a string value, and getSendAt returns the primitive string.
     */
    public function testWithSendAtFromString(): void
    {
        // Arrange
        $holder = new ImplWithMessageSendAtAccessorUnitTest();

        // Act
        $result = $holder->withSendAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getSendAt());
    }
    /**
     * Asserts that withsendAt has access to the value object
     * from a string value, and getSendAt returns the primitive string.
     */
    public function testWithSendAtFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithMessageSendAtAccessorUnitTest();

        // Act
        $result = $holder->withSendAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->sendAt()->value());
    }
    public function testChangedSendAt(): void
    {
        // Arrange
        $holder = new ImplWithMessageSendAtAccessorUnitTest();
        $original = $holder->withSendAt( (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withSendAt( (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withSendAt((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isSendAtChanged();
        $withSame = $original->isSendAtChanged( $same );
        $withDiferent = $original->isSendAtChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithMessageSendAtAccessorUnitTest
{
  use MessageSendAtAccessor;
}
